import React, { useEffect, useState } from "react";
import api from "../api/axios";

export default function Orders() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Get user from localStorage
    const user = JSON.parse(localStorage.getItem("loggedInUser"));
    
    if (!user) {
      setLoading(false);
      return;
    }

    // Note: Your controller uses session, but the endpoint takes customerId
    // You may need to use: api.get(`/orders/customer/${user.id}`) 
    // depending on how your authentication is handled.
    // Inside your useEffect
api.get(`/orders/customer/${user.id}`)
  .then(res => {
    // Ensure we only set state if the response is actually an array
    if (Array.isArray(res.data)) {
      setOrders(res.data);
    } else {
      console.error("API did not return an array:", res.data);
      setOrders([]); // Fallback to empty array
    }
    setLoading(false);
  })
  .catch(err => {
    console.error("Error fetching orders:", err);
    setOrders([]); // Fallback to empty array on error
    setLoading(false);
  });
  }, []);

  if (loading) return <div className="container mt-4">Loading orders...</div>;

  return (
    <div className="container mt-4">
      <h2 className="mb-4">My Order History</h2>

      {orders.length === 0 ? (
        <div className="alert alert-info">No orders found.</div>
      ) : (
        orders.map(order => (
          <div key={order.id} className="card mb-4 shadow-sm">
            <div className="card-header d-flex justify-content-between align-items-center">
              <span><strong>Order ID:</strong> #{order.id}</span>
              <span className={`badge ${order.status === 'DELIVERED' ? 'bg-success' : 'bg-primary'}`}>
                {order.status}
              </span>
            </div>
            
            <div className="card-body">
              <div className="row mb-3">
                <div className="col-md-6">
                  {/* Formatting the LocalDateTime from Java */}
                  <p className="mb-1"><strong>Order Date:</strong> {new Date(order.orderDate).toLocaleDateString()} {new Date(order.orderDate).toLocaleTimeString()}</p>
                  <p className="mb-0"><strong>Total Amount:</strong> ₹{order.totalAmount.toFixed(2)}</p>
                </div>
              </div>

              <h6 className="border-bottom pb-2">Ordered Products</h6>
              <div className="table-responsive">
                <table className="table table-sm table-borderless">
                  <thead>
                    <tr>
                      <th>Product</th>
                      <th>Quantity</th>
                      <th className="text-end">Price</th>
                      <th className="text-end">Subtotal</th>
                    </tr>
                  </thead>
                  <tbody>
                    {order.items && order.items.map(item => (
                      <li key={item.id} style={{ display: 'table-row' }}>
                        <td style={{ display: 'table-cell' }}>{item.product.name}</td>
                        <td style={{ display: 'table-cell' }}>{item.quantity}</td>
                        <td style={{ display: 'table-cell' }} className="text-end">₹{item.price}</td>
                        <td style={{ display: 'table-cell' }} className="text-end">₹{(item.price * item.quantity).toFixed(2)}</td>
                      </li>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
}
